# -*- coding: utf-8 -*-
"""
iFinD 金融数据接口 独立调用脚本 (standalone)
=============================================
无需 LLM，直接用 Python 调用同花顺 iFinD 全部接口。
密钥在脚本内直接配置（AUTH_TOKEN），不读取任何外部配置文件。

依赖：requests（pip install requests）

快速开始：
    from ifind_api import get_stock_info, stock_highfreq_quotes, list_tools

    # query 型接口
    r = get_stock_info("格力电器上市时间")
    print(r)

    # 结构化参数型接口（实时快照）
    r = stock_highfreq_quotes("贵州茅台", "最新价,涨跌幅,成交量", "real_time")
    print(r)

    # 查看当前密钥在某服务下的真实工具清单
    tools = list_tools("stock")
    print(tools["data"]["result"]["tools"])
"""

import json
import math

import requests

# =====================================================================
# 一、密钥与服务配置（直接在此处修改，不从文件读取）
# =====================================================================
AUTH_TOKEN = "your ifind-mcp key"  # <-- 替换为你的有效密钥

BASE = "https://api-mcp.51ifind.com:8643/ds-mcp-servers"
SERVERS = {
    "stock": f"{BASE}/hexin-ifind-ds-stock-mcp",
    "fund": f"{BASE}/hexin-ifind-ds-fund-mcp",
    "edb": f"{BASE}/hexin-ifind-ds-edb-mcp",
    "news": f"{BASE}/hexin-ifind-ds-news-mcp",
    "bond": f"{BASE}/hexin-ifind-ds-bond-mcp",
    "global_stock": f"{BASE}/hexin-ifind-ds-global-stock-mcp",
    "index": f"{BASE}/hexin-ifind-ds-index-mcp",
}

# 每次调用前是否向服务端校验工具名（会多一次 list_tools 请求）。
# 直接调用场景建议设为 False 以减少延迟；权限不确定时设为 True 更安全。
VERIFY_TOOLS = False

# =====================================================================
# 二、底层 MCP 调用机制（一般无需修改）
# =====================================================================
_sessions = {}
_req_ids = {}
_tool_sets = {}
BLOCKED_KEYS = {"__proto__", "prototype", "constructor"}


def _next_id(server_type):
    _req_ids[server_type] = _req_ids.get(server_type, 0) + 1
    return _req_ids[server_type]


def _headers(server_type=None):
    h = {
        "Content-Type": "application/json",
        "Accept": "application/json, text/event-stream",
        "Authorization": AUTH_TOKEN,
    }
    if server_type in _sessions:
        h["Mcp-Session-Id"] = _sessions[server_type]
    return h


def _post(server_type, payload, timeout=60):
    resp = requests.post(
        SERVERS[server_type],
        json=payload,
        headers=_headers(server_type),
        verify=False,
        timeout=timeout,
    )
    data = None
    if resp.text.strip():
        try:
            data = resp.json()
        except Exception:
            data = resp.text
    return resp, data


def _validate_params(params):
    if not isinstance(params, dict):
        raise TypeError("input must be a JSON object")

    def walk(value):
        if value is None:
            return
        if isinstance(value, list):
            for item in value:
                walk(item)
            return
        if isinstance(value, dict):
            for key, item in value.items():
                if key in BLOCKED_KEYS:
                    raise TypeError("input contains blocked field")
                walk(item)
            return
        if isinstance(value, float) and not math.isfinite(value):
            raise TypeError("input contains invalid number")
        if not isinstance(value, (str, int, float, bool)):
            raise TypeError("input contains unsupported value type")

    walk(params)
    json.dumps(params, allow_nan=False)


def _init(server_type):
    if server_type in _sessions:
        return

    payload = {
        "jsonrpc": "2.0",
        "id": _next_id(server_type),
        "method": "initialize",
        "params": {
            "protocolVersion": "2025-03-26",
            "capabilities": {},
            "clientInfo": {"name": "standalone-client", "version": "1.0.0"},
        },
    }

    resp, data = _post(server_type, payload, timeout=30)
    resp.raise_for_status()

    session_id = resp.headers.get("Mcp-Session-Id")
    if not session_id:
        raise RuntimeError(f"initialize 成功但未返回 Mcp-Session-Id: {data}")

    _sessions[server_type] = session_id

    notify = {"jsonrpc": "2.0", "method": "notifications/initialized"}
    requests.post(
        SERVERS[server_type],
        json=notify,
        headers=_headers(server_type),
        verify=False,
        timeout=10,
    )


def _load_tool_set(server_type):
    if server_type in _tool_sets:
        return _tool_sets[server_type]

    res = list_tools(server_type)
    tools = res.get("data", {}).get("result", {}).get("tools")
    if not isinstance(tools, list):
        raise RuntimeError("Invalid tools/list response")

    tool_set = {
        tool.get("name")
        for tool in tools
        if isinstance(tool, dict) and isinstance(tool.get("name"), str) and tool.get("name")
    }
    _tool_sets[server_type] = tool_set
    return tool_set


def call(server_type, tool_name, params):
    """发起一次接口请求。

    参数:
        server_type: 服务类型，取值 stock / fund / bond / global_stock / index / edb / news
        tool_name:   接口名（见下方各服务封装函数）
        params:      接口参数（JSON 对象）

    返回:
        dict: {"ok": bool, "status_code": int, "data": ...} 或 {"ok": False, ...}
    """
    if server_type not in SERVERS:
        raise ValueError(f"unknown server_type: {server_type}")

    _validate_params(params)
    if VERIFY_TOOLS:
        allowed_tools = _load_tool_set(server_type)
        if tool_name not in allowed_tools:
            raise ValueError(f"toolName not allowed for server_type {server_type}: {tool_name}")

    payload = {
        "jsonrpc": "2.0",
        "id": _next_id(server_type),
        "method": "tools/call",
        "params": {"name": tool_name, "arguments": params},
    }

    resp, data = _post(server_type, payload)

    if isinstance(data, dict) and "error" in data:
        return {
            "ok": False,
            "status_code": resp.status_code,
            "error": data["error"],
            "raw": data,
        }

    resp.raise_for_status()
    return {"ok": True, "status_code": resp.status_code, "data": data}


def list_tools(server_type):
    """获取指定服务当前可用的真实工具清单（含 inputSchema 参数定义）。"""
    if server_type not in SERVERS:
        raise ValueError(f"unknown server_type: {server_type}")

    _init(server_type)

    payload = {
        "jsonrpc": "2.0",
        "id": _next_id(server_type),
        "method": "tools/list",
        "params": {},
    }

    resp, data = _post(server_type, payload)

    if isinstance(data, dict) and "error" in data:
        return {
            "ok": False,
            "status_code": resp.status_code,
            "error": data["error"],
            "raw": data,
        }

    resp.raise_for_status()
    return {"ok": True, "status_code": resp.status_code, "data": data}


# =====================================================================
# 三、接口封装函数（36 个接口，按服务分组）
#    query 型接口：query 为自然语言查询串，格式「主体+指标+时间」
#    高频行情接口：使用结构化参数 symbols / indicators / data_mode / interval
# =====================================================================

# ------------------------- 股票服务 stock -------------------------
def search_stocks(query):
    """智能选股。query: 自然语言选股条件，如 "电子行业市值大于100亿" """
    return call("stock", "search_stocks", {"query": query})


def get_stock_summary(query):
    """股票信息摘要。query: 股票简称+查询内容，如 "茅台财务状况" """
    return call("stock", "get_stock_summary", {"query": query})


def get_stock_info(query):
    """股票基本资料。query: 股票简称+指标名称+时间，如 "格力电器上市时间" """
    return call("stock", "get_stock_info", {"query": query})


def get_stock_performance(query):
    """股票日频行情与技术指标。query: 股票简称+指标名称+时间，如 "三花智控近5日涨跌幅" """
    return call("stock", "get_stock_performance", {"query": query})


def get_stock_shareholders(query):
    """股本结构与股东数据。query: 股票简称+指标，如 "光明乳业流通股占比" """
    return call("stock", "get_stock_shareholders", {"query": query})


def get_stock_financials(query):
    """财务数据与指标。query: 股票简称+财务指标+财报日期，如 "科大讯飞2025年三季度的ROE" """
    return call("stock", "get_stock_financials", {"query": query})


def get_risk_indicators(query):
    """风险定量指标。query: 股票+时间+指标，如 "航天电子在2026-03-19的夏普比率" """
    return call("stock", "get_risk_indicators", {"query": query})


def get_stock_events(query):
    """上市公司重大事件类指标。query: 股票+事件相关指标，如 "摩尔线程IPO首发股本数量" """
    return call("stock", "get_stock_events", {"query": query})


def get_esg_data(query):
    """ESG评级数据。query: 股票+ESG评级指标，如 "诚意药业中诚信ESG评级" """
    return call("stock", "get_esg_data", {"query": query})


def stock_highfreq_quotes(symbols, indicators, data_mode, interval=None):
    """A股实时快照与高频序列（结构化参数）。

    symbols:    多个主体英文逗号拼接，上限10个，如 "300033.SZ,300059,贵州茅台"
    indicators: 多个指标英文逗号拼接，上限10个，如 "开盘价,最高价,最低价,收盘价,涨跌幅,成交量"
    data_mode:  "real_time"（实时快照）或 "highfreq"（高频序列）
    interval:   仅 highfreq 时有效，分钟周期 1/3/5/10/15/30/60
    """
    params = {"symbols": symbols, "indicators": indicators, "data_mode": data_mode}
    if interval is not None:
        params["interval"] = interval
    return call("stock", "stock_highfreq_quotes", params)


# ------------------------- 基金服务 fund -------------------------
def search_funds(query):
    """基金搜索。query: 模糊基金名称或选基需求，如 "南方基金新能源ETF" """
    return call("fund", "search_funds", {"query": query})


def get_fund_profile(query):
    """基金基本资料。query: 基金名称+指标，如 "工银双盈债券A(010068)的发行日期与发行费率" """
    return call("fund", "get_fund_profile", {"query": query})


def get_fund_market_performance(query):
    """基金行情与业绩。query: 基金名称+时间范围+指标，如 "方正富邦策略精选A(010072)在近一月收益率" """
    return call("fund", "get_fund_market_performance", {"query": query})


def get_fund_ownership(query):
    """基金份额与持有人。query: 基金名称+日期+指标，如 "湘财长弘灵活配置混合A(010076)在2025-06-30的申购总份额和赎回总份额" """
    return call("fund", "get_fund_ownership", {"query": query})


def get_fund_portfolio(query):
    """基金持仓明细。query: 基金名称+日期+指标，如 "工银优质成长混合A(010088)在2025-06-30披露报告中的股票投资占比" """
    return call("fund", "get_fund_portfolio", {"query": query})


def get_fund_financials(query):
    """基金财务指标。query: 基金名称+日期+指标，如 "泰康浩泽混合A(010081)在2025-06-30的利润" """
    return call("fund", "get_fund_financials", {"query": query})


def get_fund_company_info(query):
    """基金公司信息。query: 基金名称+所属基金公司维度指标，如 "蜂巢丰瑞的所属基金公司基金经理数量" """
    return call("fund", "get_fund_company_info", {"query": query})


def fund_highfreq_quotes(symbols, indicators, data_mode, interval=None):
    """公募基金实时快照与高频序列（结构化参数）。

    symbols:    如 "000307.OF,516850,易方达蓝筹精选混合"
    indicators: 如 "最新价,IOPV净值估值,振幅,折价"
    data_mode:  "real_time" / "highfreq"
    interval:   仅 highfreq 时有效，分钟周期 1/3/5/10/15/30/60
    """
    params = {"symbols": symbols, "indicators": indicators, "data_mode": data_mode}
    if interval is not None:
        params["interval"] = interval
    return call("fund", "fund_highfreq_quotes", params)


# ------------------------- 债券服务 bond -------------------------
def bond_basic_info(query):
    """债券基本信息与发债主体资料。query: 债券简称/代码+查询内容，如 "23广东11的发行期限与发行总额" """
    return call("bond", "bond_basic_info", {"query": query})


def bond_market_data(query):
    """债券行情数据与估值分析。query: 债券简称/代码+指标+时间，如 "26国债01近五日收盘价、涨跌幅与最新久期、凸性" """
    return call("bond", "bond_market_data", {"query": query})


def bond_financial_data(query):
    """债券发债主体财务数据与指标。query: 债券简称/代码+时间+指标，如 "24辽港01、24皮城01在20251231的资产负债率和ROE" """
    return call("bond", "bond_financial_data", {"query": query})


def bond_special_data(query):
    """债券特殊指标（信用债评级、回购、可转债条款等）。query: 债券简称/代码+指标，如 "华海转债、南航转债的最新转股价格及转换比例" """
    return call("bond", "bond_special_data", {"query": query})


def bond_highfreq_quotes(symbols, indicators, data_mode, interval=None):
    """债券实时快照与高频序列（结构化参数，仅交易所债券，不含银行间）。

    symbols:    如 "240025.IB,199222,大连2521"
    indicators: 如 "开盘价,最高价,最低价,收盘价,成交量"
    data_mode:  "real_time" / "highfreq"
    interval:   仅 highfreq 时有效，分钟周期 1/3/5/10/15/30/60
    """
    params = {"symbols": symbols, "indicators": indicators, "data_mode": data_mode}
    if interval is not None:
        params["interval"] = interval
    return call("bond", "bond_highfreq_quotes", params)


# ------------------------- 港美股服务 global_stock -------------------------
def search_global_stocks(query, market):
    """港美股智能选股。query: 选股条件，market: "港股"/"美股"，如 ("汽车行业且市盈率低于50", "港股") """
    return call("global_stock", "search_global_stocks", {"query": query, "market": market})


def global_stock_profile(query):
    """港美股基本资料与股本结构。query: 股票名称/代码+指标，如 "智谱、minimax的所属行业、上市日期与发行价" """
    return call("global_stock", "global_stock_profile", {"query": query})


def global_stock_quotes(query):
    """港美股行情数据与技术指标。query: 股票名称/代码+时间+指标，如 "苹果和特斯拉近10个交易日的涨跌幅、换手率" """
    return call("global_stock", "global_stock_quotes", {"query": query})


def global_stock_financial(query):
    """港美股财务数据与估值指标。query: 股票名称/代码+指标，如 "Google和Meta在最新报告期的ROE、ROA、利润增速" """
    return call("global_stock", "global_stock_financial", {"query": query})


def global_stock_events(query):
    """港美股公告事件（IPO、回购、分红、ESG等）。query: 股票名称/代码+事件指标，如 "minimax的IPO日期、数量、价格及保荐人" """
    return call("global_stock", "global_stock_events", {"query": query})


# ------------------------- 指数板块服务 index -------------------------
def index_data(query):
    """指数行情、技术指标与估值指标。query: 指数名称+时间+指标，如 "沪深300、中证2000过去10个交易日的涨跌幅和收盘点数" """
    return call("index", "index_data", {"query": query})


def sector_data(query):
    """板块行情、财务分析与成分股指标。query: 板块名称+时间+指标，如 "医疗设备板块(中证行业)的成分股个数及过去5个交易日的成分股平均涨跌幅" """
    return call("index", "sector_data", {"query": query})


def index_highfreq_quotes(symbols, indicators, data_mode, interval=None):
    """指数实时快照与高频序列（结构化参数）。

    symbols:    如 "000001.SH,000941,创业板指"
    indicators: 如 "最高价,最新价,涨跌幅,上涨家数"
    data_mode:  "real_time" / "highfreq"
    interval:   仅 highfreq 时有效，分钟周期 1/3/5/10/15/30/60
    """
    params = {"symbols": symbols, "indicators": indicators, "data_mode": data_mode}
    if interval is not None:
        params["interval"] = interval
    return call("index", "index_highfreq_quotes", params)


# ------------------------- 宏观行业服务 edb -------------------------
def search_edb(query):
    """指标搜索（先搜再查）。query: 行业/产品/指标描述，如 "光模块产业链相关指标" """
    return call("edb", "search_edb", {"query": query})


def get_edb_data(query):
    """指标数据查询。query: 指标名称+时间范围，如 "光伏电池产量202301-202506" """
    return call("edb", "get_edb_data", {"query": query})


# ------------------------- 新闻公告服务 news -------------------------
def search_news(query, time_start=None, time_end=None, size=None):
    """新闻资讯语义检索。query: 内容；time_start/time_end: 日期区间；size: 返回数量 """
    params = {"query": query}
    if time_start is not None:
        params["time_start"] = time_start
    if time_end is not None:
        params["time_end"] = time_end
    if size is not None:
        params["size"] = size
    return call("news", "search_news", params)


def search_notice(query, time_start=None, time_end=None, size=None):
    """公告语义检索。query: 内容；time_start/time_end: 日期区间；size: 返回数量 """
    params = {"query": query}
    if time_start is not None:
        params["time_start"] = time_start
    if time_end is not None:
        params["time_end"] = time_end
    if size is not None:
        params["size"] = size
    return call("news", "search_notice", params)


def search_trending_news(keyword, industry_name=None, time_scope=None, size=None):
    """热点事件资讯查询。keyword: 关键词；industry_name: 行业；time_scope: 时效范围如 "24小时"；size: 返回数量 """
    params = {"keyword": keyword}
    if industry_name is not None:
        params["industry_name"] = industry_name
    if time_scope is not None:
        params["time_scope"] = time_scope
    if size is not None:
        params["size"] = size
    return call("news", "search_trending_news", params)


# =====================================================================
# 四、主入口（仅作示例说明，不会自动发起网络请求）
# =====================================================================
if __name__ == "__main__":
    print("iFinD 金融数据接口独立调用脚本")
    print("请在脚本顶部 AUTH_TOKEN 中配置有效密钥，然后在你的代码中：")
    print("    from ifind_api import get_stock_info, stock_highfreq_quotes")
    print("    r = get_stock_info(\"格力电器上市时间\")")
    print("    r = stock_highfreq_quotes(\"贵州茅台\", \"最新价,涨跌幅\", \"real_time\")")

